import React, { useState, useEffect } from 'react';
import {
  TextField, Button, Container, Typography, Paper, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Chip, Box, Alert, Toolbar,
  CssBaseline, useMediaQuery, Zoom, Grid, ThemeProvider, createTheme, Fade,
} from '@mui/material';
import { green, red, blue, grey } from '@mui/material/colors';

const theme = createTheme({
  palette: {
    primary: {
      main: blue[900], // Professional dark blue
    },
    secondary: {
      main: green[700], // Calm green
    },
    background: {
      default: '#f4f6f8',
      paper: '#ffffff',
    },
    error: {
      main: red[700],
    },
  },
  typography: {
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    h4: {
      fontWeight: 700,
      letterSpacing: '0.1em',
      color: blue[900],
    },
    h5: {
      fontWeight: 600,
      color: '#333',
    },
    button: {
      textTransform: 'none',
      fontWeight: 600,
      borderRadius: 6,
      padding: '10px 20px',
      boxShadow: 'none',
    },
  },
  shape: {
    borderRadius: 6,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          transition: 'background-color 0.3s ease, box-shadow 0.3s ease',
          '&:hover': {
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            backgroundColor: blue[800],
          },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          boxShadow: '0 8px 24px rgba(0,0,0,0.1)',
          padding: '24px',
          borderRadius: 6,
          backgroundColor: '#fff',
        },
      },
    },
    MuiTableCell: {
      styleOverrides: {
        root: {
          fontSize: 14,
          padding: '10px 12px',
        },
        head: {
          backgroundColor: blue[900],
          color: '#fff',
          fontWeight: 700,
          fontSize: 14,
          letterSpacing: '0.05em',
        },
      },
    },
  },
});

function App() {
  const [website, setWebsite] = useState('');
  const [monitoringStatus, setMonitoringStatus] = useState('Idle');
  const [threatDetected, setThreatDetected] = useState(false);
  const [message, setMessage] = useState('');
  const [threatLogs, setThreatLogs] = useState([]);

  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const startMonitoring = async () => {
    if (!website) {
      setMessage('Please enter a website URL.');
      return;
    }
    setMessage('');
    try {
      const response = await fetch('http://127.0.0.1:5001/start_monitoring', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ website }),
      });
      const data = await response.json();
      if (response.ok) {
        setMessage(data.message);
        setMonitoringStatus('Monitoring');
      } else {
        setMessage(data.error || 'Failed to start monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  const stopMonitoring = async () => {
    try {
      const response = await fetch('http://127.0.0.1:5001/stop_monitoring', { method: 'POST' });
      if (response.ok) {
        setMonitoringStatus('Idle');
        setThreatDetected(false);
        setThreatLogs([]);
        setMessage('Monitoring stopped.');
      } else {
        setMessage('Failed to stop monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  useEffect(() => {
    setThreatLogs([]);

    let interval = null;

    if (monitoringStatus === 'Monitoring') {
      interval = setInterval(async () => {
        try {
          const response = await fetch('http://127.0.0.1:5001/status');
          const data = await response.json();
          setMonitoringStatus(data.status);
          setThreatDetected(data.threat_detected);

          const logsResponse = await fetch('http://127.0.0.1:5001/threat_logs');
          const logsData = await logsResponse.json();
          const cleanedLogs = logsData.map(log => {
            let cleanedWebsite = log.website;
            if (cleanedWebsite.startsWith('http://')) {
              cleanedWebsite = cleanedWebsite.slice(7);
            } else if (cleanedWebsite.startsWith('https://')) {
              cleanedWebsite = cleanedWebsite.slice(8);
            }
            return { ...log, website: cleanedWebsite };
          });
          setThreatLogs(cleanedLogs);
        } catch (error) {
          setMonitoringStatus('Error');
          setThreatDetected(false);
          setThreatLogs([]);
        }
      }, 5000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [monitoringStatus]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'Monitoring':
        return blue[900];
      case 'Idle':
        return grey[600];
      case 'Starting':
        return blue[600];
      default:
        return grey[600];
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Container maxWidth="md" sx={{ mt: 6, mb: 6 }}>
        <Typography variant={isMobile ? 'h5' : 'h3'} align="center" sx={{ fontWeight: 'bold', mb: 4, color: blue[900] }}>
          Cyber Threat Detection System
        </Typography>
        <Typography variant="h6" align="center" sx={{ mb: 5, color: '#555' }}>
          Real-time Website Cyber Threat Monitoring and Detection
        </Typography>
        <Paper sx={{ p: 4, mb: 6, borderRadius: 6, boxShadow: '0 8px 24px rgba(0,0,0,0.1)' }}>
          <Box
            component="form"
            onSubmit={(e) => {
              e.preventDefault();
              startMonitoring();
            }}
            sx={{
              display: 'flex',
              flexDirection: isMobile ? 'column' : 'row',
              gap: 2,
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <TextField
              label="Website URL"
              variant="outlined"
              fullWidth
              value={website}
              onChange={(e) => setWebsite(e.target.value)}
              required
              sx={{ flexGrow: 1 }}
            />
            <Button variant="contained" color="primary" type="submit" sx={{ py: 1.8, minWidth: 150 }}>
              Start Monitoring
            </Button>
            <Button variant="outlined" color="error" sx={{ py: 1.8, minWidth: 150 }} onClick={stopMonitoring}>
              Stop Monitoring
            </Button>
          </Box>
          {message && (
            <Zoom in={Boolean(message)}>
              <Alert severity="info" sx={{ mt: 3, borderRadius: 3, fontWeight: 'medium' }}>
                {message}
              </Alert>
            </Zoom>
          )}
          <Box sx={{ mt: 5, textAlign: 'center' }}>
            <Typography variant="h6" component="span" sx={{ fontWeight: 'medium' }}>
              Status:
            </Typography>
            <Chip
              label={monitoringStatus}
              sx={{
                ml: 1,
                bgcolor: threatDetected ? red[700] : getStatusColor(monitoringStatus),
                color: 'white',
                fontWeight: 'bold',
                fontSize: 16,
                px: 3,
                py: 0.5,
                borderRadius: 6,
                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                transition: 'background-color 0.5s ease',
              }}
            />
            {threatDetected && (
              <Fade in={threatDetected} timeout={600}>
                <Alert
                  severity="error"
                  sx={{
                    mt: 3,
                    borderRadius: 6,
                    fontWeight: 'bold',
                    fontSize: 16,
                    boxShadow: '0 6px 20px rgba(211,47,47,0.7)',
                    transition: 'all 0.5s ease',
                  }}
                >
                  Threat Detected on the website!
                </Alert>
              </Fade>
            )}
          </Box>
        </Paper>
        <Paper sx={{ p: 4, borderRadius: 6, boxShadow: '0 8px 24px rgba(0,0,0,0.1)', maxHeight: 450, overflowY: 'auto' }}>
          <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', mb: 3, color: blue[900] }}>
            Threat Detection Log
          </Typography>
          {threatLogs.length === 0 ? (
            <Typography variant="body1" color="text.secondary" align="center" sx={{ fontStyle: 'italic', mt: 2 }}>
              No threats detected yet.
            </Typography>
          ) : (
            <Table stickyHeader aria-label="threat detection log table">
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold' }}>Timestamp</TableCell>
                  <TableCell sx={{ fontWeight: 'bold' }}>Website</TableCell>
                  <TableCell sx={{ fontWeight: 'bold' }}>Threat Name</TableCell>
                  <TableCell sx={{ fontWeight: 'bold' }}>Message</TableCell>
                  <TableCell sx={{ fontWeight: 'bold' }}>Solution</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {threatLogs.map((log) => (
                  <TableRow key={log.id} hover sx={{ '&:hover': { backgroundColor: grey[100] } }}>
                    <TableCell>{log.timestamp}</TableCell>
                    <TableCell>{log.website}</TableCell>
                    <TableCell>{log.threat_name}</TableCell>
                    <TableCell>{log.message}</TableCell>
                    <TableCell>{log.solution}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </Paper>
      </Container>
    </ThemeProvider>
  );
}

export default App;
